import { expect, test } from 'bun:test';
import sample from '../../data/synthetic/fixtures/dive-garmin-like.csv' with { type: 'text' };
import garbage from '../../data/synthetic/fixtures/shopping-list.csv' with { type: 'text' };
import parse from './index';
test('known value on sample', () => { const s = parse(sample, { filename: 'dive.csv' }); expect(s.series.depth_m).toBeDefined(); expect(s.durationSec).toBeGreaterThan(5); });
test('garbage throws ParseError', () => { expect(() => parse(garbage, { filename: 'x.csv' })).toThrow(/ParseError/); });
test('empty input throws, does not crash the process', () => { expect(() => parse('', { filename: '' })).toThrow(); });
